using System.Collections.Concurrent;

namespace JqSharp.Tests;

// Ported from gojq compiler_test.go, including its checks of the generated bytecode.
public class CompilerTests
{
    [Fact]
    public void Should_ReportErrors_When_IndexingNonObjects()
    {
        JqCode code = JqQuery.Parse(".foo").Compile();
        object?[] inputs = { null, "string", 42, new List<object?> { "foo" }, new Dictionary<string, object?> { ["foo"] = 42 } };
        List<string> got = new();
        foreach (object? input in inputs)
        {
            try
            {
                got.AddRange(code.Run(input).Select(static v => JqValue.ToJson(v)));
            }
            catch (JqException err)
            {
                got.Add(err.Message);
            }
        }

        Assert.Equal(new[]
        {
            "null",
            "expected an object but got: string (\"string\")",
            "expected an object but got: number (42)",
            "expected an object but got: array ([\"foo\"])",
            "42",
        }, got);
    }

    [Fact]
    public void Should_FoldConstants_When_ArrayAndObjectAreConstant()
    {
        JqCode code = JqQuery.Parse("[1,{foo:2,\"bar\":+3},[-4]]").Compile();

        Assert.Equal(3, code.Codes.Length);
        Assert.Equal("[1,{\"bar\":3,\"foo\":2},[-4]]", JqValue.ToJson(code.Run(null).Single()));
    }

    [Fact]
    public void Should_CompileConstantIndices_When_IndexingAndSlicing()
    {
        JqCode code = JqQuery.Parse(".foo.\"bar\".[\"baz\"].[-1].\"\".[0:1]").Compile();

        Assert.Equal(8, code.Codes.Length);
        Assert.Equal(new object?[] { null }, code.Run(null).ToList());
    }

    [Fact]
    public void Should_UseSetpath_When_AssigningConstantPath()
    {
        JqCode code = JqQuery.Parse(".foo.\"bar\".[\"baz\"].[0].\"\".[0:1] = [0]").Compile();

        Assert.Equal(8, code.Codes.Length);
        Assert.Equal("{\"foo\":{\"bar\":{\"baz\":[{\"\":[0]}]}}}", JqValue.ToJson(code.Run(null).Single()));
    }

    [Fact]
    public void Should_JumpInsteadOfCall_When_WhileRecurses()
    {
        JqCode code = JqQuery.Parse("0 | while(. < 10; . + 1)").Compile();

        Assert.Equal(48, code.Codes.Length);
        Assert.Equal(code.Codes[2].Op, code.Codes[21].Op);
        Assert.Equal(Enumerable.Range(0, 10).Select(static i => (object?)(long)i), code.Run(null).ToList());
    }

    [Fact]
    public void Should_UseCallRec_When_TailCallNeedsScope()
    {
        JqCode code = JqQuery.Parse("def f: . as $x | $x, (if $x < 3 then $x + 1 | f else empty end), $x; f").Compile();

        Assert.Equal(48, code.Codes.Length);
        Assert.Equal(Opcode.CallRec, code.Codes[39].Op);
        Assert.Equal(Opcode.Call, code.Codes[38].Op);
    }

    [Fact]
    public void Should_ShortcutJumps_When_FunctionsAreDefined()
    {
        JqCode code = JqQuery.Parse("def f: 1; def g: 2; def h: 3; f").Compile();

        Assert.Equal(15, code.Codes.Length);
        Assert.Equal(13, code.Codes[1].V);
        Assert.Equal(new object?[] { 1L }, code.Run(null).ToList());
    }

    [Theory]
    [InlineData("^", 1)]
    [InlineData(" ^", 2)]
    [InlineData(" ^ ", 2)]
    [InlineData("\U0001F44D", 4)]
    [InlineData(" \U0001F44D", 5)]
    [InlineData(" \U0001F44D ", 5)]
    [InlineData("test\U0001F44D", 8)]
    public void Should_ReportByteOffset_When_ParseFails(string src, int offset)
    {
        JqParseException err = Assert.Throws<JqParseException>(() => JqQuery.Parse(src));

        Assert.Equal(offset, err.Offset);
    }

    [Fact]
    public void Should_EmitRange_When_CodeRunsConcurrently()
    {
        JqCode code = JqQuery.Parse("range(10)").Compile();

        Parallel.For(0, 10, _ => Assert.Equal(Enumerable.Range(0, 10).Select(static i => (object?)(long)i), code.Run(null).ToList()));
    }

    [Fact]
    public void Should_ShareRegexCache_When_CodeRunsConcurrently()
    {
        JqCode code = JqQuery.Parse("\"abcdefg\" | test(\"cd\"), split(\"e\") | . == true or length > 0").Compile();

        Parallel.For(0, 10, _ => Assert.All(code.Run(null), static v => Assert.Equal(true, v)));
    }

    [Fact]
    public void Should_ConsumeEachInputOnce_When_InputIsReadConcurrently()
    {
        const int n = 10;
        JqCode code = JqQuery.Parse("input").Compile(new JqCompilerOptions { InputIter = Enumerable.Range(0, n).Select(static i => (object?)i) });
        ConcurrentDictionary<object, bool> seen = new();

        Parallel.For(0, n, _ => Assert.True(seen.TryAdd(code.Run(null).First()!, true)));

        Assert.Equal(Enumerable.Range(0, n).Select(static i => (object)(long)i).OrderBy(static x => x), seen.Keys.OrderBy(static x => x));
    }
}
